import{_ as d,a0 as r,w as s,s as i,ao as p,I as o,x as t,a1 as n,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Red Hat正与Intel紧密协作，力争在Fedora 21中默认加入Wayland | LCTT x X-CMD","titleTemplate":false,"description":"Red Hat正与Intel紧密协作，力争在Fedora 21中默认加入Wayland | LCTT (201309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Red Hat正与Intel紧密协作，力争在Fedora 21中默认加入Wayland | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Red Hat正与Intel紧密协作，力争在Fedora 21中默认加入Wayland | LCTT (201309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201309/Red Hat and Intel Working Closely to Bring Wayland as Default for Fedora 21","title":"Red Hat正与Intel紧密协作，力争在Fedora 21中默认加入Wayland","tag":"201309","desc":""},"relativePath":"201309/Red Hat and Intel Working Closely to Bring Wayland as Default for Fedora 21.md","filePath":"[post].md"}'),f={name:"201309/Red Hat and Intel Working Closely to Bring Wayland as Default for Fedora 21.md"};function u(y,a,C,W,m,I){const e=r("Link");return s(),i("div",null,[a[11]||(a[11]=p('<h1 id="red-hat正与intel紧密协作-力争在fedora-21中默认加入wayland" tabindex="-1">Red Hat正与Intel紧密协作，力争在Fedora 21中默认加入Wayland <a class="header-anchor" href="#red-hat正与intel紧密协作-力争在fedora-21中默认加入wayland" aria-label="Permalink to “Red Hat正与Intel紧密协作，力争在Fedora 21中默认加入Wayland”">​</a></h1><p><strong>为了使Wayland支持GNOME，Red Hat与Intel的开发者紧密合作，希望能为Wayland加入Fedora21做好及时准备。</strong></p><p>Ubuntu曾企图征服FOSS（Free and Open Source Software自由和开源软件）世界的秘密计划被Intel的一纸声明挫败，至少到现在为止，Ubuntu仍未能翻身。但如今，Intel开发者的真正计划也被揭露了。</p><p>抛开那些戏剧化的剧情，实际上Intel为Wayland的未来投入巨资已不是秘密，Intel的开发者们正加紧与Red Hat的合作，争取将GNOME Shell变为一个&quot;码农&quot;（译注，意指GNOME Shell只完成表层的外围工作）。</p><p>来自Red Hat的Christian Schaller在他的个人博客中写道：“我们在Red Hat的团队一直在和我们的同行Intel紧密协作，合并并稳固相关的补丁包，保证Wayland能够支持GNOME，同时查看堆栈中还有哪些地方需要进一步改进。”</p><p>看起来这个小组当前的目标是为Fedora 20准备一个足够的技术预览版本，至少目前是这样。这不是一个正式项目，但至少应该会给人们一个值得期待的idea。</p><p>Ubuntu13.10预定于10月份发布，在这个特殊的时间点上，Canonical是否会急切的使出全力推出Mir，目前还并不明朗。</p><p>Schaller在他的博客中还写道，“因此，一旦确信用户不会感到负面影响，我们才会最终用Wayland替代X服务器。所以，在Fedora 21中默认采用Wayland还是X服务器，这仍然是一个悬而未决的问题。”</p><p>这场显示服务端之间的“战争”即将决出一个赢家，那就是终端用户。为了提供更好的用户体验，决战双方，Intel和Canonical都更加充满斗志。无论谁胜谁负，最终受益的都将是我们这些用户。</p>',9)),o("p",null,[a[1]||(a[1]=t("via:",-1)),n(e,{href:"http://news.softpedia.com/news/Red-Hat-and-Intel-Working-Closely-to-Bring-Wayland-as-Default-for-Fedora-21-383119.shtml"},{default:l(()=>[...a[0]||(a[0]=[t("http://news.softpedia.com/news/Red-Hat-and-Intel-Working-Closely-to-Bring-Wayland-as-Default-for-Fedora-21-383119.shtml",-1)])]),_:1})]),o("p",null,[a[4]||(a[4]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[2]||(a[2]=[t("LCTT",-1)])]),_:1}),a[5]||(a[5]=t(" 原创翻译，",-1)),n(e,{href:"http://linux.cn/portal.php"},{default:l(()=>[...a[3]||(a[3]=[t("Linux中国",-1)])]),_:1}),a[6]||(a[6]=t(" 荣誉推出",-1))]),o("p",null,[a[9]||(a[9]=t("译者：",-1)),n(e,{href:"http://linux.cn/space/14801"},{default:l(()=>[...a[7]||(a[7]=[t("Mr小眼儿",-1)])]),_:1}),a[10]||(a[10]=t(" 校对：",-1)),n(e,{href:"http://linux.cn/space/14763"},{default:l(()=>[...a[8]||(a[8]=[t("Caroline",-1)])]),_:1})])])}const F=d(f,[["render",u]]);export{_ as __pageData,F as default};
